import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();

    if (!email || !password) {
      setError("Email et mot de passe requis");
      return;
    }

    try {
      const res = await fetch("http://localhost:5000/api/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.error || "Erreur serveur");
        return;
      }

      // Redirection selon rôle
      if (data.user.role === "student") navigate("/dashboard-student");
      else if (data.user.role === "prof") navigate("/dashboard-prof");

    } catch (err) {
      setError("Erreur serveur");
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      padding: "20px"
    }}>
      <div style={{
        background: "white",
        borderRadius: "12px",
        boxShadow: "0 10px 30px rgba(0, 0, 0, 0.2)",
        padding: "40px",
        width: "100%",
        maxWidth: "420px",
        textAlign: "center"
      }}>
        <h2 style={{ color: "#333", marginBottom: "10px", fontSize: "28px" }}>Connexion</h2>
        <p style={{ color: "#666", marginBottom: "30px" }}>Accédez à votre espace personnel</p>

        <form onSubmit={handleLogin}>
          {error && <p style={{ color: "red", marginBottom: "15px" }}>{error}</p>}

          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={{
              width: "100%",
              padding: "12px 15px",
              marginBottom: "20px",
              border: "1px solid #ddd",
              borderRadius: "8px",
              fontSize: "16px",
              outline: "none",
              boxSizing: "border-box"
            }}
          />

          <input
            type="password"
            placeholder="Mot de passe"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{
              width: "100%",
              padding: "12px 15px",
              marginBottom: "20px",
              border: "1px solid #ddd",
              borderRadius: "8px",
              fontSize: "16px",
              outline: "none",
              boxSizing: "border-box"
            }}
          />

          <button
            type="submit"
            style={{
              width: "100%",
              padding: "14px",
              backgroundColor: "#667eea",
              color: "white",
              border: "none",
              borderRadius: "8px",
              fontSize: "16px",
              fontWeight: "600",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(102, 126, 234, 0.4)",
              transition: "all 0.3s ease"
            }}
            onMouseOver={(e) => { e.target.style.backgroundColor = "#5a6fd8"; e.target.style.transform = "translateY(-2px)"; }}
            onMouseOut={(e) => { e.target.style.backgroundColor = "#667eea"; e.target.style.transform = "translateY(0)"; }}
          >
            Se connecter
          </button>
        </form>

        <p style={{ marginTop: "25px", color: "#666", fontSize: "15px" }}>
          Pas de compte ? <a href="/register" style={{ color: "#667eea", textDecoration: "none", fontWeight: "500" }}
            onMouseOver={(e) => e.target.style.color = "#5a6fd8"}
            onMouseOut={(e) => e.target.style.color = "#667eea"}
          >S'inscrire</a>
        </p>
      </div>
    </div>
  );
}

export default Login;
